<?php
require_once __DIR__.'/includes/helpers.php'; require_login(); $title=t('nav.sites');
$q=trim($_GET['q']??''); $level=$_GET['level']??''; $city=$_GET['city']??''; $where='WHERE status="active"'; $params=[];
if($q!==''){ $where.=' AND (name LIKE ? OR city LIKE ? OR site_type LIKE ?)'; $like="%$q%"; $params=[$like,$like,$like]; }
if(in_array($level,['منخفض','متوسط','مرتفع'],true)){ $where.=' AND risk_level=?'; $params[]=$level; }
if($city!==''){ $where.=' AND city=?'; $params[]=$city; }
$sites=site_list($where,$params); $cities=fetch_all('SELECT DISTINCT city FROM ae_heritage_sites ORDER BY city'); $mapData=site_map_data($where,$params); include __DIR__.'/includes/header.php';
?>
<section class="page-hero"><span class="eyebrow"><?= h(localized('قاعدة بيانات المواقع','Heritage Site Database')) ?></span><h1><?= h(t('nav.sites')) ?></h1><p><?= h(localized('استعرض المواقع المسجلة وافتح تفاصيل الموقع والتقارير المعتمدة، أو استخدم الخريطة الحرارية لمعرفة المناطق الأعلى خطورة.','Browse registered sites and approved reports, or use the heatmap to identify the highest-risk areas.')) ?></p></section>
<form class="filters" method="get"><input class="form-control" name="q" value="<?= h($q) ?>" placeholder="<?= h(localized('ابحث باسم الموقع أو المدينة أو النوع','Search by site, city, or type')) ?>"><select class="form-select" name="level"><option value=""><?= h(localized('كل مستويات الخطورة','All Risk Levels')) ?></option><?php foreach(['منخفض','متوسط','مرتفع'] as $l): ?><option value="<?= h($l) ?>" <?= $level===$l?'selected':'' ?>><?= h(risk_label($l)) ?></option><?php endforeach; ?></select><select class="form-select" name="city"><option value=""><?= h(localized('كل المدن','All Cities')) ?></option><?php foreach($cities as $c): ?><option value="<?= h($c['city']) ?>" <?= $city===$c['city']?'selected':'' ?>><?= h($c['city']) ?></option><?php endforeach; ?></select><button class="btn btn-primary"><i class="ti ti-search"></i><?= h(t('common.search')) ?></button></form>
<div class="map-card" style="margin-bottom:24px"><div class="map-toolbar"><div><h2 style="color:var(--green);margin:0"><?= h(localized('خريطة المواقع','Site Map')) ?></h2><p class="muted" style="margin:5px 0 0"><?= h(localized('يمكن التبديل بين علامات المواقع والخريطة الحرارية.','Switch between site markers and the risk heatmap.')) ?></p></div><div class="map-controls"><button class="btn btn-primary" type="button" data-map-mode="markers"><?= h(localized('علامات المواقع','Site Markers')) ?></button><button class="btn btn-light" type="button" data-map-mode="heat"><?= h(t('nav.map')) ?></button></div></div><div id="heritageMap" class="map-wrap medium"></div></div>
<div class="site-grid"><?php foreach($sites as $site): ?><article class="site-card"><div class="site-art"><span class="sun"></span><span class="castle" style="background:<?= h(risk_class($site['risk_level'])==='danger'?'#8f5b55':(risk_class($site['risk_level'])==='warning'?'#8c7657':'#637c67')) ?>"><i></i></span></div><div class="site-body"><span class="badge badge-<?= h(risk_class($site['risk_level'])) ?>"><?= h(risk_label($site['risk_level'])) ?> — <?= (int)$site['risk_percentage'] ?>%</span><h3 class="site-title"><?= h($site['name']) ?></h3><div class="site-meta"><span><i class="ti ti-map-pin"></i><?= h($site['city']) ?></span><span><i class="ti ti-building-fortress"></i><?= h($site['site_type']) ?></span></div><p class="muted"><?= h(excerpt($site['description'],120)) ?></p><a class="btn btn-light" href="site.php?id=<?= (int)$site['id'] ?>"><i class="ti ti-file-description"></i><?= h(localized('التفاصيل والتقارير','Details & Reports')) ?></a></div></article><?php endforeach; ?></div>
<script>window.ATHAR_SITES=<?= json_encode($mapData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;window.ATHAR_LANG=<?= json_encode(current_lang()) ?>;</script><script src="assets/js/map.js?v=14.0"></script>
<?php include __DIR__.'/includes/footer.php'; ?>
